// localReadme looks for a README file in the current working directory.
func localReadme() (*RepoReadme, error) {
	candidates := []string{"README.md", "README.markdown", "README.mdown", "README.mkdown", "README"}
	for _, filename := range candidates {
		if _, err := os.Stat(filename); err == nil {
			content, err := ioutil.ReadFile(filename)
			if err != nil {
				return nil, err
			}
			return &RepoReadme{
				Filename: filename,
				Content:  string(content),
			}, nil
		}
	}
	return nil, nil
